local out=peripheral.find("monitor") or term.current(); term.redirect(out); term.clear(); term.setCursorPos(1,1); print("NEXUS TERMINAL 0.4.0"); print("Type help, ps, devices, reboot, shutdown, or a CraftOS command."); while true do write("nexus$ "); local line=read(); if line=="exit" then break elseif line=="ps" then for _,p in ipairs(NEXUS.ps()) do print(p.pid,p.state,p.name) end elseif line=="devices" then for n,d in pairs(NEXUS.devices) do print(n,d.kind,d.online and "ONLINE" or "OFFLINE") end elseif line=="reboot" then os.reboot() elseif line=="shutdown" then os.shutdown() elseif line=="" then else local ok,err=pcall(function() shell.run(line) end); if not ok then printError(err) end end end
